<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useLessonReviewStore } from '@/stores/lessonReview'
import { formatReviewTime } from '@/utils/lessonReview'
import { frameStateCounts, participantState, studentStateColor, studentStateName, visibleParticipation } from '@/utils/studentStates'
import type { ActivityFrame } from '@/types/lessonReview'
import { reviewTerm } from '@/utils/reviewPresentation'
import VisionFrameReview from './VisionFrameReview.vue'
import { overallEngagement, engagementWeights } from '@/utils/classEngagement'

const props = defineProps<{ frame: ActivityFrame | null; compact?: boolean }>()
const store = useLessonReviewStore()
const imageError = ref(false)
const labelMode = ref<'compact' | 'labels' | 'boxes'>('compact')
const selectedTrack = ref('')
const visual = ref<HTMLElement | null>(null)
const fullscreenError = ref('')
const selected = computed(() => props.frame?.participants.find(person => person.track_id === selectedTrack.value))
const reference = computed(() => props.frame?.visual_reference)
const engagementByFrame = computed(() => new Map(overallEngagement(store.data?.activity_analysis?.frames || []).map(row => [row.frame_id, row])))
const overall = computed(() => props.frame ? engagementByFrame.value.get(props.frame.id) || overallEngagement([props.frame])[0] : null)
const referenceValue = computed(() => reference.value ? overall.value?.smoothed_index : participation.value?.index)
const hasReference = computed(() => referenceValue.value !== null && referenceValue.value !== undefined)
async function enlarge() { try { await visual.value?.requestFullscreen(); fullscreenError.value = '' } catch { fullscreenError.value = 'Fullscreen is unavailable in this environment. Check the source image in Original frame evidence' } }
const width = computed(() => props.frame?.width || 1280)
const height = computed(() => props.frame?.height || 720)
const participation = computed(() => props.frame ? visibleParticipation(props.frame) : null)
const counts = computed(() => props.frame ? frameStateCounts(props.frame) : [])
const hasIndex = computed(() => participation.value?.index !== null && participation.value?.index !== undefined)
const hasActions = computed(() => participation.value?.active_fraction !== null && participation.value?.active_fraction !== undefined)
const nearestObserved = computed(() => store.data?.activity_analysis?.frames.find(row => row.detected_people > 0))
const strongestActions = computed(() => store.data?.activity_analysis?.frames.reduce<ActivityFrame | null>((best, row) => {
  const current = row.participation?.active_people || 0
  return current >= 3 && current > (best?.participation?.active_people || 0) ? row : best
}, null))
const sampleTime = (seconds: number) => `${formatReviewTime(seconds)}.${Math.floor((seconds % 1) * 10 + .00001)}`
watch(() => props.frame?.image_url, () => { imageError.value = false })
</script>

<template>
  <section class="student-state" :class="{ compact }" data-testid="current-student-state" aria-label="Student behavior in the current frame">
    <div class="state-heading"><div><p class="eyebrow">{{ compact ? 'Student behavior at this time' : 'Place states in their lesson context' }}</p><h3>{{ frame?.detected_people ? `Currently detected ${frame.detected_people} people` : frame ? 'No visible people were detected at this time' : 'State unknown at this time' }}</h3></div><span class="frame-clock mono" data-testid="current-student-frame">{{ frame ? formatReviewTime(frame.timestamp_sec) : store.timeText }}</span></div>
    <p v-if="reference" class="candidate-notice" data-testid="state-candidate-notice">Seven-class model candidates · Not yet reviewed against human annotations for this lesson</p>
    <div class="state-layout">
      <div class="state-visual">
        <div v-if="frame?.participants.length && !compact" class="annotation-tools" aria-label="Detection overlay mode"><div><button v-for="mode in (['compact','labels','boxes'] as const)" :key="mode" :class="{ active: labelMode === mode }" :aria-pressed="labelMode === mode" @click="labelMode = mode">{{ { compact: 'Compact annotations', labels: 'State labels', boxes: 'Boxes only' }[mode] }}</button></div><button @click="enlarge">Fullscreen review ↗</button></div>
        <p v-if="fullscreenError" class="state-boundary">{{ fullscreenError }}</p>
        <div v-if="frame?.image_url && !imageError" ref="visual" class="annotated-frame" :class="{ 'full-labels': labelMode === 'labels' }" :style="{ aspectRatio: `${width}/${height}` }">
          <img :src="frame.image_url" :alt="`${formatReviewTime(frame.timestamp_sec)} Behavior sample frame from the original video`" @error="imageError = true" />
          <svg :viewBox="`0 0 ${width} ${height}`" role="group" aria-label="Visible person boxes and state cues" data-testid="student-state-boxes">
            <g v-for="(person, index) in frame.participants" :key="person.track_id" class="person-observation" :class="{ selected: selectedTrack === person.track_id }" :style="{ color: studentStateColor(participantState(person)) }" role="button" tabindex="0" :aria-label="`Person to verify ${index + 1} ${studentStateName(participantState(person))}`" @click="selectedTrack = person.track_id" @keydown.enter="selectedTrack = person.track_id" @keydown.space.prevent="selectedTrack = person.track_id">
              <title>{{ person.track_id }} · {{ studentStateName(participantState(person)) }}{{ person.student_state?.evidence?.length ? ` · ${person.student_state.evidence.join('; ')}` : '' }}</title>
              <rect :x="person.bbox[0]" :y="person.bbox[1]" :width="person.bbox[2] - person.bbox[0]" :height="person.bbox[3] - person.bbox[1]" class="person-box" />
              <rect v-if="labelMode !== 'boxes'" class="person-label-bg" :x="Math.min(person.bbox[0], width - (labelMode === 'labels' && !compact ? 170 : 43))" :y="Math.max(0, person.bbox[1] - 22)" :width="labelMode === 'labels' && !compact ? 170 : 43" height="22" rx="3" />
              <text v-if="labelMode !== 'boxes'" :x="Math.min(person.bbox[0], width - (labelMode === 'labels' && !compact ? 170 : 43)) + 6" :y="Math.max(0, person.bbox[1] - 22) + 16">{{ String(index + 1).padStart(2, '0') }}{{ labelMode === 'labels' && !compact ? ` ${studentStateName(participantState(person))}` : '' }}</text>
            </g>
          </svg>
          <span class="image-badge">Source frame · State overlay</span>
        </div>
        <div v-else class="state-image-empty"><span class="empty-viewfinder">⌖</span><p>{{ imageError ? 'Source frame currently unavailable' : frame ? 'No source frame is available at this time' : 'No behavior sample interval at this time' }}</p><small>{{ frame ? 'Visible states follow the actual sampled records' : 'Gaps remain unknown. Does not reuse the previous frame' }}</small></div>
        <p v-if="frame" class="image-caption"><span>Scene {{ frame.scene_id }} · {{ sampleTime(frame.start_sec) }}–{{ sampleTime(frame.end_sec) }}</span><button @click="store.seek(frame.timestamp_sec)">Replay this moment ↗</button></p>
        <div v-if="selected && !compact" class="selected-observation" data-testid="selected-observation"><div><strong>{{ studentStateName(participantState(selected)) }}</strong><button aria-label="Hide person details" @click="selectedTrack = ''">Collapse</button></div><p>State source {{ reviewTerm(selected.student_state?.source || 'unavailable') }} · Confidence {{ selected.student_state?.confidence === null || selected.student_state?.confidence === undefined ? 'Unknown' : `${(selected.student_state.confidence * 100).toFixed(1)}%` }}</p><small>{{ selected.student_state?.evidence.join('; ') }}. IDs are linked within the current scene only. Identity not established</small></div>
      </div>
      <div class="state-reading">
        <div class="participation-reading"><div><span class="reading-label">{{ reference ? 'Overall student engagement' : 'Detected participation action fraction' }}</span><p><strong v-if="reference" :class="{ unknown: !hasReference }" data-testid="overall-engagement-index">{{ hasReference ? referenceValue!.toFixed(1) : overall?.status === 'no_people' ? 'No observations' : 'No score available' }}</strong><strong v-else :class="{ unknown: !hasActions }" data-testid="visible-action-fraction">{{ hasActions ? (participation!.active_fraction! * 100).toFixed(0) : 'Unknown' }}</strong><span v-if="reference && hasReference">/ 100</span><span v-else-if="!reference && hasActions">%</span></p></div><div class="participation-mark" :class="{ unknown: reference ? !hasReference : !hasActions }"><i :style="{ '--value': reference ? (hasReference ? `${referenceValue}%` : '0%') : (hasActions ? `${participation!.active_fraction! * 100}%` : '0%') }"></i><span>{{ reference ? 'Engagement' : 'Visible cues' }}</span></div></div>
        <p v-if="reference" class="action-count" data-testid="engagement-support">Valid behaviors <b>{{ overall?.scored_people || 0 }} / {{ frame?.detected_people || 0 }}</b> people<span v-if="overall?.status === 'limited_support'"> · Limited-support estimate</span><span v-else-if="hasReference"> · Behavior estimate</span></p><p v-else-if="hasActions" class="action-count" data-testid="visible-action-count">Detected <b>{{ participation!.active_people }} / {{ participation!.total_people }}</b> people reading, writing, or raising a hand</p>
        <div v-if="reference" class="participation-reference"><span>Behavior score coverage</span><strong data-testid="engagement-coverage">{{ overall?.support_fraction === null || overall?.support_fraction === undefined ? 'No observations' : `${(overall.support_fraction * 100).toFixed(0)}%` }}</strong><small>Scored people / Detected people · Retains estimates with a notice when coverage is low</small></div>
        <div v-else class="participation-reference"><span>Behavioral engagement reference</span><strong data-testid="visible-participation">{{ hasIndex ? participation!.index!.toFixed(1) : 'Unknown' }}<small v-if="hasIndex"> / 100</small></strong><small>{{ hasIndex ? 'Based only on detected participation actions' : 'Insufficient current action evidence' }}</small></div>
        <p v-if="participation?.total_people" class="state-coverage">Recognized cues <b>{{ participation.observed_people }} / {{ participation.total_people }}</b> people<span v-if="participation.unknown_people"> · {{ participation.unknown_people }} unknown</span></p>
        <p v-else class="state-coverage">{{ frame ? 'No usable people. Participation unknown' : 'No current observations. Participation unknown' }}</p>
        <div class="state-counts" data-testid="student-state-counts"><div v-for="[label, count] in counts" :key="label"><i :style="{ background: studentStateColor(label) }"></i><span>{{ studentStateName(label) }}</span><b>{{ count }}</b></div><p v-if="!counts.length">{{ frame?.detected_people ? 'No interpretable state labels are available' : 'No student states are available' }}</p></div>
        <details v-if="reference && !compact" class="reference-policy"><summary>Scoring rules and coverage</summary><p>{{ Object.entries(engagementWeights).map(([label, weight]) => `${studentStateName(label)} ${(weight * 100).toFixed(0)} points`).join(' / ') }}</p><p>Retains the original project weights for seven behavior classes. Average valid behaviors. Then multiply by exp(-0.6 × standard deviation) to apply the class dispersion adjustment. Consecutive observations in the same scene use 0.3 × previous value + 0.7 × current value smoothing. Smoothing restarts after a scene change or missing observation.</p><p>Fewer than 3 scored people or coverage below 60% triggers a limited-support estimate notice. Existing scores are retained. Unknown states and geometric pose cues are not assigned zero scores. No gaze score is added when actual gaze data is absent. This is an auxiliary overall behavior estimate. It is not a probability of psychological engagement or an individual student grade.</p></details>
        <button v-if="!hasIndex && strongestActions" class="locate-observation" data-testid="locate-participation-actions" @click="store.seek(strongestActions.timestamp_sec)">View explicit participation actions <span class="mono">{{ formatReviewTime(strongestActions.timestamp_sec) }} →</span></button>
        <button v-if="!frame?.detected_people && nearestObserved" class="locate-observation" @click="store.seek(nearestObserved.timestamp_sec)">Find a lesson frame containing people <span class="mono">{{ formatReviewTime(nearestObserved.timestamp_sec) }} →</span></button>
      </div>
    </div>
    <VisionFrameReview v-if="!compact && store.data" :lesson-id="store.data.lesson.id" :frame="frame" @lock="store.seek" />
    <p class="state-boundary">Undetected actions do not imply nonparticipation. Pose cues are listed separately; Person role is unconfirmed. They cannot establish psychological engagement or knowledge mastery.</p>
  </section>
</template>

<style scoped>
