margin-top:7px;display:flex;align-items:baseline;gap:6px}.participation-reading strong{font-size:38px;font-weight:500;letter-spacing:-.04em;color:#26436c;line-height:1.2}.participation-reading strong.unknown{font-size:29px;color:#627da2;letter-spacing:0}.participation-reading p>span{font-size:10px;color:#607ca4}.participation-mark{display:flex;align-items:center;gap:6px;font-size:8px;color:#627da2;writing-mode:vertical-rl}.participation-mark i{display:block;width:7px;height:54px;border-radius:4px;background:linear-gradient(to top,#5b7fb2 var(--value),#d5e3f7 var(--value))}.participation-mark.unknown i{background:repeating-linear-gradient(135deg,#c1cfe2,#c1cfe2 3px,#dde9f9 3px,#dde9f9 6px)}.state-coverage{font-size:9px;line-height:1.9;color:#5f7ca5;margin-top:9px}.state-coverage b{font-weight:500;color:#4c6a94}.state-counts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px 14px;border-top:1px solid #d4e3f7;margin-top:13px;padding-top:13px}.state-counts>div{display:flex;align-items:center;gap:7px;font-size:10px;color:#58749c;min-width:0;line-height:1.7}.state-counts span{min-width:0;overflow-wrap:anywhere;white-space:normal}.state-counts b{flex-shrink:0}.state-counts i{width:7px;height:7px;border-radius:2px;flex-shrink:0}.state-counts b{font-weight:500;font-size:12px;color:#355179;margin-left:auto}.state-counts p{grid-column:1/-1;font-size:10px;color:#607ca4;line-height:1.8}.state-boundary{font-size:9px;line-height:1.9;color:#607ca4;margin-top:13px}.locate-observation{display:flex;justify-content:space-between;gap:8px;width:100%;text-align:left;padding:9px 10px;background:#dde9f9;color:#4b6992;border-radius:5px;font-size:9px;line-height:1.7;margin-top:12px}.locate-observation span{white-space:nowrap}.compact .state-layout{display:flex;flex-direction:column-reverse;gap:14px}.compact .state-heading{margin-bottom:11px}.compact .state-heading h3{font-size:12px}.compact .frame-clock{font-size:10px;padding:5px 7px}.compact .state-reading{padding:0}.compact .participation-reading strong{font-size:32px}.compact .participation-reading strong.unknown{font-size:23px}.compact .participation-mark{writing-mode:horizontal-tb;flex-direction:column-reverse;gap:7px}.compact .participation-mark i{width:52px;height:5px;background:linear-gradient(to right,#5b7fb2 var(--value),#d5e3f7 var(--value))}.compact .state-coverage{margin-top:6px}.compact .state-counts{padding-top:10px;margin-top:10px;gap:7px 14px}.compact .state-boundary{font-size:8px;margin-top:9px}.compact .image-caption{font-size:8px}.compact .image-caption button{font-size:8px}
@media(max-width:1000px){.state-layout{grid-template-columns:1fr}.state-reading{padding:0}.state-counts{grid-template-columns:repeat(3,minmax(0,1fr))}.compact .state-counts{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:550px){.state-counts{grid-template-columns:repeat(2,minmax(0,1fr))}.state-heading h3{font-size:14px}.state-heading .eyebrow{font-size:8px}.participation-reading strong{font-size:34px}}
.annotation-tools{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px;font-size:9px}.annotation-tools>div{display:flex;padding:3px;gap:3px;border:1px solid #dce7f9;border-radius:7px;background:#f0f6ff}.annotation-tools button{font-size:9px;background:transparent;color:#6d88af;padding:5px 7px;border-radius:4px}.annotation-tools button.active{color:#2a63bb;background:#fff;box-shadow:0 1px 4px #275da410}.person-observation{cursor:pointer;outline:none}.person-observation .person-label-bg{fill:#285caa;fill-opacity:.9}.annotated-frame text{fill:#fff;font-size:17px;font-weight:500}.person-observation.selected .person-box,.person-observation:focus-visible .person-box{stroke:#163e8c;stroke-width:4;fill-opacity:.13}.person-observation.selected .person-label-bg{fill:#123d87}.annotated-frame:fullscreen{width:100vw;height:100vh;background:#10213b;border-radius:0;aspect-ratio:auto!important}.annotated-frame:fullscreen>img,.annotated-frame:fullscreen>svg{object-fit:contain}.selected-observation{margin-top:12px;padding:12px;border:1px solid #d3e3fb;background:#f2f7ff;border-radius:8px;color:#557bad;font-size:10px;line-height:1.8}.selected-observation>div{display:flex;justify-content:space-between;gap:12px}.selected-observation strong{font-size:11px;font-weight:600;color:#2d5c9e}.selected-observation button{font-size:9px;background:none;color:#7c96b9}.selected-observation p{margin-top:6px}.selected-observation small{font-size:9px;display:block;margin-top:5px;overflow-wrap:anywhere}.reference-policy{margin-top:13px;padding:10px 12px;border:1px solid #dce7f8;background:#f7faff;border-radius:7px;color:#7890b3;font-size:9px;line-height:1.9}.reference-policy summary{cursor:pointer;color:#547db5}.reference-policy p{margin-top:8px}.compact .participation-reference{margin-top:9px;padding:7px 9px}.compact .state-counts{max-height:95px;overflow:auto}
